def count_special_numbers(n, k):
    if n == 1:
        return 1 if k == 0 else 0

    binary = bin(n)[2:]
    length = len(binary)

    @lru_cache(maxsize=None)
    def dp(pos, ops, tight):
        if pos == length:
            return 1 if ops == k else 0

        result = 0
        limit = int(binary[pos]) if tight else 1

        for bit in range(limit + 1):
            new_tight = tight and (bit == limit)
            new_ops = ops + (bit == 1)
            result += dp(pos + 1, new_ops, new_tight)
            result %= MOD

        return result

    return dp(0, 0, True)

