def count_special_numbers(n, k):
    @lru_cache(maxsize=None)
    def dfs(num, ops):
        if ops > k:
            return 0
        if ops == k and num == 1:
            return 1
        result = 0
        for bit in range(n.bit_length()):
            if num & (1 << bit):
                result += dfs(num ^ (1 << bit), ops + 1)
        return result % MOD

